declare const _default: "\n\n#ifndef _DECODE_INCLUDED_\n#define _DECODE_INCLUDED_\n\nvec3 decodeLinear(vec4 raw) {\n    return raw.rgb;\n}\n\n// the exact sRGB transfer, as the GPU decodes an sRGB texture, with (raw + 0.055) / 1.055 and\n// raw / 12.92 written as a multiply-add and a multiply\nfloat decodeGamma(float raw) {\n    return raw <= 0.04045 ? raw * 0.0773993808 : pow(raw * 0.9478672986 + 0.0521327014, 2.4);\n}\n\nvec3 decodeGamma(vec3 raw) {\n    return mix(pow(raw * 0.9478672986 + 0.0521327014, vec3(2.4)), raw * 0.0773993808, lessThanEqual(raw, vec3(0.04045)));\n}\n\nvec3 decodeGamma(vec4 raw) {\n    return decodeGamma(raw.xyz);\n}\n\nvec3 decodeRGBM(vec4 raw) {\n    vec3 color = (8.0 * raw.a) * raw.rgb;\n    return color * color;\n}\n\nvec3 decodeRGBP(vec4 raw) {\n    vec3 color = raw.rgb * (-raw.a * 7.0 + 8.0);\n    return color * color;\n}\n\nvec3 decodeRGBE(vec4 raw) {\n    if (raw.a == 0.0) {\n        return vec3(0.0, 0.0, 0.0);\n    } else {\n        return raw.xyz * pow(2.0, raw.w * 255.0 - 128.0);\n    }\n}\n\nvec4 passThrough(vec4 raw) {\n    return raw;\n}\n\nvec3 unpackNormalXYZ(vec4 nmap) {\n    return nmap.xyz * 2.0 - 1.0;\n}\n\nvec3 unpackNormalXY(vec4 nmap) {\n    vec3 normal;\n    normal.xy = nmap.wy * 2.0 - 1.0;\n    normal.z = sqrt(1.0 - clamp(dot(normal.xy, normal.xy), 0.0, 1.0));\n    return normal;\n}\n\n#endif\n";
export default _default;
